import{_ as e,o as t,c as a,a4 as r}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛公告","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛公告","date":"2026-04-30T00:00:00.000Z","source":"中国农业信息网","category":"news","link":"https://www.agri.cn/xxh/zhny/202604/t20260430_8832820.htm","summary":"为贯彻落实党中央、国务院关于发展人工智能的决策部署，大力推进人工智能赋能农业农村发展，农业农村部信息中心、河北省农业农村厅、雄安新区管理委员会共同主办2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛，搭建产学研用相结合的综合展示平台，将产业界、科技界好产品好技术赛出来，充分调动各类社会主体积极投身智慧农业建设。现将有关事项公告如下。\\n一、大赛主题\\n中文：\\nAI农业 慧创未来\\n英文：\\n...\\n","contentHash":"4307f024f0419ac033631b9c435d61d8","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-04-30-2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛公告.md","filePath":"news/2026-04-30-2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛公告.md"}'),_={name:"news/2026-04-30-2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛公告.md"};function n(s,p,o,l,c,i){return t(),a("div",null,[...p[0]||(p[0]=[r('<h1 id="_2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛公告" tabindex="-1">2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛公告 <a class="header-anchor" href="#_2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛公告" aria-label="Permalink to &quot;2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛公告&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.agri.cn/xxh/zhny/202604/t20260430_8832820.htm" target="_blank" rel="noreferrer">中国农业信息网</a><br> 日期: 2026-04-30 摘要: 为贯彻落实党中央、国务院关于发展人工智能的决策部署，大力推进人工智能赋能农业农村发展，农业农村部信息中心、河北省农业农村厅、雄安新区管理委员会共同主办2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛，搭建产学研用相结合的综合展示平台，将产业界、科技界好产品好技术赛出来，充分调动各类社会主体积极投身智慧农业建设。现将有关事项公告如下。 一、大赛主题 中文： AI农业 慧创未来 英文： ...</p></blockquote><p>为贯彻落实党中央、国务院关于发展人工智能的决策部署，大力推进人工智能赋能农业农村发展，农业农村部信息中心、河北省农业农村厅、雄安新区管理委员会共同主办2026年智慧农业创新大赛暨雄安智慧农业技术应用大赛，搭建产学研用相结合的综合展示平台，将产业界、科技界好产品好技术赛出来，充分调动各类社会主体积极投身智慧农业建设。现将有关事项公告如下。</p><p>一、大赛主题</p><p>中文：AI农业 慧创未来</p><p>英文：AI Agriculture，Better Future</p><p>二、时间和地点</p><p>时间：6月28日报到，7月2日决赛，如遇天气变化，考虑将户外比赛提前举行，室内比赛时间不变。</p><p>地点：河北雄安新区</p><p>三、组织机构</p><p>主办单位：农业农村部信息中心、河北省农业农村厅、雄安新区管理委员会</p><p>承办单位：河北省农业信息中心、雄安新区农业农村局</p><p>为保证大赛公信力与专业性，大赛设置专家裁判组，主要负责赛事设计、规则制定、现场执裁等事项，并向主办方提出意见建议。</p><p>四、参赛对象</p><p>大赛秉持开门办赛原则，参赛主体应为具有独立法人资格的企业、事业单位、科研院所和高校等机构。</p><p>五、赛道设置</p><p>大赛聚焦农业生产中的关键环节与技术难点，坚持应用导向，设置以下6个赛道。</p><p>（一）智能农机作业控制赛道。重点考核智能农机无人驾驶系统的路径规划、轨迹跟踪控制、旋耕作业质量等能力。比赛成绩根据复杂路径生成与优化能力、农机无人干预下的自主导航精度、行驶稳定性及机具精准升降控制逻辑等指标判定。</p><p>（二）无人机巡田解决方案赛道。围绕水稻、甘蓝大田监测场景，提交一套完整的无人机巡田解决方案，完成水稻倒伏监测、甘蓝缺苗识别、杂草监测三项任务。比赛成绩根据解决方案的识别准确性与作业效率等指标判定。</p><p>（三）激光除草机器人赛道。重点考核机器人杂草精准识别定位、激光高效清除与作物损伤控制、真实农田场景适配及全自主作业等核心能力。比赛成绩根据除草精准性、作业效率、自主导航完成度等指标判定。</p><p>（四）设施小番茄采摘机器人赛道。重点考核机器人的目标识别定位、采摘执行机械设计、采摘行为控制等能力。比赛成绩根据成熟果串检测识别、果串剪断位置决策、作业效率和避障能力等指标判定。</p><p>（五）家禽巡检机器人赛道。重点考核小规模叠层笼养蛋鸡养殖场景下，机器人的自主导航行走、目标识别定位、多层巡检作业等能力。比赛成绩根据机器人的避障与导航性能，蛋鸡笼内死鸡、绝产鸡检测识别准确性和作业时长等指标判定。</p><p>（六）鱼群智能检测赛道。重点考核水下设备的场景适应与部署、智能感知与算法、系统处理等能力。比赛成绩根据设备独立作业能力和智能化水平、游动鱼群识别统计与生物特征测量准确性等指标判定。</p><p>赛道规则（征求意见稿）附后，如有意见建议，请于本公告发布之日起10个工作日内，将意见建议发送至xxzxyjgh@163.com，邮件标题注明“赛道规则意见反馈+单位/个人名称”。专家裁判组将对收集到的意见建议进行综合研究并合理采纳，恕不逐一回复。</p><p>六、参赛条件</p><p>（一）参赛主体条件</p><p>1.参赛主体应为具有独立法人资格的企事业单位；报名信息须准确、真实、有效，一经发现弄虚作假，将取消参赛资格。</p><p>2.被列入“信用中国”网站记录失信被执行人、重大税收违法案件当事人名单、政府采购严重违法失信行为记录名单的单位不得参赛。</p><p>3.参赛主体不允许联合参赛。同一个主体可申报多个赛道，但每个赛道只能申报1个参赛产品。</p><p>（二）参赛产品条件</p><p>1.参赛产品须符合所报赛道主题，装备整机国产化率应不低于80%，并提供相关证明材料。</p><p>2.参赛单位应具有参赛产品的知识产权，签署并提交《参赛承诺书》，不得存在任何专利权、著作权、商标权及其他知识产权纠纷，且不得违反国家相关法律法规，否则立即取消参赛资格或比赛成绩。</p><p>3.参赛产品应具备创新性、先进性、可推广性等特点，能够提供方案架构、关键技术、产品、平台及核心优势，描述可量化价值。</p><p>（三）报名方式</p><p>1.登录<a href="https://ai.ntv.xn--cn-q24c08gyu1ak8n" target="_blank" rel="noreferrer">https://ai.ntv.cn注册报名</a>。报名不收取任何费用。参赛报名表和承诺书须签字盖章后上传电子版，纸质版邮寄至农业农村部信息中心。</p><p>2.提交产品说明书和设备应用情况视频等介绍材料，特别要说明国产化情况，视频时长3分钟以内，大小不超过1000M。</p><p>3.提交相关证明材料，包括参赛单位基本资质、责任声明、信用情况等证明材料，以及参赛项目相关的基本资质证明、应用案例证明、知识产权证明等材料。所有材料须为参赛单位所有，严禁使用母公司、分公司、子公司、控股公司或其他非参赛单位材料，否则将取消参赛资格。</p><p>七、成绩设置</p><p>依据比赛成绩，对各赛道前3/5名的参赛单位及对应产品型号颁发成绩单，具体名额根据参赛队伍数量确定。</p><p>八、配套服务</p><p>（一）展示推介</p><p>赛前征集参赛产品相关视频、宣传素材，在全国智慧农业现场推进会播放展示。决赛期间在雄安新区设立线下展示专区，通过海报、实物和视频等形式，为优秀参赛产品进行展示洽谈。赛后在农业农村部官网“智慧农业在行动”专栏、中国农业农村信息网等平台对优秀参赛产品进行宣传推介。</p><p>（二）产融对接</p><p>邀请银行、投融资机构代表，以及参赛产品上下游企事业单位代表作为专业观众观赛，在赛场开辟对接专区，赛后组织对接活动。</p><p>（三）推广应用</p><p>通过我部举办的相关展会和活动进行宣传推介，优先纳入河北省智慧农业推荐目录，优先推荐在河北省智慧农业项目中应用推广，其单位优先参与主办单位举办的相关培训交流活动。</p><p>（四）落地孵化</p><p>参赛单位有机会获得推荐入驻雄安未来之城场景汇主题楼宇，享受拎包入住、人才公寓、租金减免等优惠条件，及孵化转化服务。符合雄安新区《关于促进未来之城场景汇成果转化落地支持创新载体高质量发展的若干措施》及“雄才十六条”政策的企业，将按照规定获得支持，符合首都功能疏解政策的可获得资金安排落户雄安。</p><p>九、联系方式</p><p>（一）农业农村部信息中心</p><p>联系人：韦科、田景艳</p><p>电  话：010-59192201、59191722</p><p>地  址：北京市朝阳区太阳宫北街1号</p><p>（二）河北省农业农村厅</p><p>联系人：兰海龙</p><p>电  话：0311-86256822</p><p>（三）雄安新区农业农村局</p><p>联系人：孙明</p><p>电  话：0312-5628031</p><p>附件：1.参赛报名表</p><p>2.参赛承诺书</p><p>3.赛道规则（征求意见稿）</p><p>农业农村部信息中心</p><p>河北省农业农村厅</p><p>雄安新区管理委员会</p><p>2026年4月30日</p><p><a href="https://www.agri.cn/xxh/zhny/202604/t20260430_8832820.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',67)])])}const d=e(_,[["render",n]]);export{f as __pageData,d as default};
